/**
 * Definition for _Node.
 * class _Node {
 *     val: number
 *     neighbors: _Node[]
 *
 *     constructor(val?: number, neighbors?: _Node[]) {
 *         this.val = (val===undefined ? 0 : val)
 *         this.neighbors = (neighbors===undefined ? [] : neighbors)
 *     }
 * }
 *
 */

function cloneGraph(node: _Node | null): _Node | null {
  if (node === null) return null;

  // оригинал -> его копия; заодно служит множеством посещённых узлов
  const copies = new Map<_Node, _Node>();

  const dfs = (orig: _Node): _Node => {
    // Узел уже скопирован (мы пришли по циклу) — возвращаем готовую копию
    const existing = copies.get(orig);
    if (existing) return existing;

    // Создаём копию и регистрируем её ДО обхода соседей,
    // иначе на цикле рекурсия будет бесконечной
    const copy = new _Node(orig.val);
    copies.set(orig, copy);

    // Соседи копии — копии соседей оригинала
    for (const nb of orig.neighbors) {
      copy.neighbors.push(dfs(nb));
    }
    return copy;
  };

  return dfs(node);
}

// Время: O(V + E) — каждый узел копируется один раз, каждое ребро просматривается дважды
// Память: O(V) — карта копий и стек рекурсии
